INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 30, 'theory', 'Quiz: async in Python and Rust');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 30, 0, 'What happens when you call an async fn in Rust without .await and without giving it to a runtime?', '["the function runs immediately", "a Future is created, the body has not run: nothing happens", "a compile error", "the function is started on a separate thread"]', 1, 'A Future is lazy: the body runs only on poll, which the executor performs.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 30, 1, 'What replaces asyncio.gather in Rust?', '["the join! macro (or try_join!)", "the sleep function", "the cancel method", "the ? operator"]', 0, 'join! waits for all the futures and returns a tuple of results; try_join! stops at the first error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 30, 2, 'Where is the event loop in Rust?', '["in the standard library", "in the compiler", "in a runtime library, for example tokio", "in the operating system"]', 2, 'std has only Future, Poll, Context and Waker; the loop, timers and networking come from a runtime.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 30, 3, 'What should you do with blocking code inside a tokio async task?', '["nothing, tokio will cope", "send it to spawn_blocking", "add await after it", "wrap it in an async block"]', 1, 'A blocking call occupies a worker thread; spawn_blocking sends it to a separate pool.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 30, 4, 'What happens to a future that is dropped before it completes?', '["it finishes in the background", "it causes a panic", "it returns None", "it stops at the nearest .await, and the values are freed by destructors"]', 3, 'Cancellation in Rust is just destruction; that is why code must survive a stop between any two .await points.');
